package com.amar.slackclone.message;import com.amar.slackclone.user.User;import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="channel_message_attachments") public class ChannelMessageAttachment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="message_id")Message message;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="uploaded_by")User uploadedBy;String originalFileName;String storageKey;String mimeType;Long fileSize;OffsetDateTime createdAt;@PrePersist void create(){createdAt=OffsetDateTime.now();}public Long getId(){return id;}public Message getMessage(){return message;}public void setMessage(Message v){message=v;}public void setUploadedBy(User v){uploadedBy=v;}public String getOriginalFileName(){return originalFileName;}public void setOriginalFileName(String v){originalFileName=v;}public String getStorageKey(){return storageKey;}public void setStorageKey(String v){storageKey=v;}public String getMimeType(){return mimeType;}public void setMimeType(String v){mimeType=v;}public Long getFileSize(){return fileSize;}public void setFileSize(Long v){fileSize=v;}}
